function hashString(str: string): number {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < str.length; i++) {
    h = Math.imul(h ^ str.charCodeAt(i), 16777619);
  }
  return h >>> 0;
}

function createPRNG(seed: number) {
  let s = seed >>> 0;
  return function() {
    s = (s + 0x6D2B79F5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function geoDistSq(lat1: number, lon1: number, lat2: number, lon2: number) {
  const dLat = lat1 - lat2;
  const dLon = (lon1 - lon2) * Math.cos(((lat1 + lat2) * Math.PI) / 360);
  return dLat * dLat + dLon * dLon;
}

// Select 5 to 15 organic, non-coordinated opportunity points from the country's candidate pool.
// Seeded deterministically per cycle so there is zero per-frame jitter, but each cycle is unique!
export function selectCycleOpportunities(
  country: FocusCountry,
  cycleIndex: number,
  sessionSeed: number = 2026
): ActiveOpportunity[] {
  const seed = hashString(`${country.iso}_c${cycleIndex}_s${sessionSeed}`);
  const prng = createPRNG(seed);

  const isLarge = ["USA", "RUS", "BRA", "CAN", "CHN", "AUS"].includes(country.iso);
  // Opportunity count strictly clamped between 5 and 10 for all nations
  const minCount = isLarge ? 6 : 5;
  const maxCount = 10;
  const targetCount = Math.max(5, Math.min(10, minCount + Math.floor(prng() * (maxCount - minCount + 1))));

  // Soft minimum distance to prevent direct stacking while allowing organic varied spacing
  const minSepDeg = isLarge ? 3.6 : 1.4;
  const minSepSq = minSepDeg * minSepDeg;

  const pool = country.candidatePool;
  // Seeded Fisher-Yates shuffle
  const indices = pool.map((_, i) => i);
  for (let i = indices.length - 1; i > 0; i--) {
    const j = Math.floor(prng() * (i + 1));
    const tmp = indices[i];
    indices[i] = indices[j];
    indices[j] = tmp;
  }

  const selectedIndices: number[] = [];
  for (let i = 0; i < indices.length && selectedIndices.length < targetCount && selectedIndices.length < 10; i++) {
    const idx = indices[i];
    const pt = pool[idx];
    let tooClose = false;
    for (const sIdx of selectedIndices) {
      const sPt = pool[sIdx];
      if (geoDistSq(pt[0], pt[1], sPt[0], sPt[1]) < minSepSq) {
        tooClose = true;
        break;
      }
    }
    if (!tooClose) {
      selectedIndices.push(idx);
    }
  }

  // Ensure at least 5 points (strictly clamped between 5 and 10)
  while (selectedIndices.length < 5 && pool.length >= 5) {
    let bestIdx = -1;
    let bestDist = -1;
    for (const idx of indices) {
      if (selectedIndices.includes(idx)) continue;
      const pt = pool[idx];
      let minD = Infinity;
      for (const sIdx of selectedIndices) {
        const sPt = pool[sIdx];
        const d = geoDistSq(pt[0], pt[1], sPt[0], sPt[1]);
        if (d < minD) minD = d;
      }
      if (minD > bestDist) {
        bestDist = minD;
        bestIdx = idx;
      }
    }
    if (bestIdx >= 0 && selectedIndices.length < 10) selectedIndices.push(bestIdx);
    else break;
  }

  // Staggered organic intervals (~280ms to 480ms with seeded timing variation)
  let currentDelay = 0;
  return selectedIndices.map((idx, sOrder) => {
    if (sOrder > 0) {
      const interval = 280 + Math.floor(prng() * 200);
      currentDelay += interval;
    }
    const pt = pool[idx];
    return {
      lat: pt[0],
      lon: pt[1],
      delayMs: currentDelay
    };
  });
}

// Packed Int8 country membership: (cIdx + 1) per dot, where 0 = none, 1..14 = country index + 1
const PACKED_COUNTRY_DATA = "";

function unpackCountryData(): Int8Array {
  if (typeof atob === "undefined") {
    return new Int8Array(0);
  }
  const cBin = atob(PACKED_COUNTRY_DATA);
  const len = cBin.length;
  const countryIds = new Int8Array(len);

  for (let i = 0; i < len; i++) {
    const rawVal = cBin.charCodeAt(i);
    countryIds[i] = rawVal === 0 ? -1 : (rawVal - 1);
  }
  return countryIds;
}

export const DOT_COUNTRY_IDS: Int8Array = unpackCountryData();
